@Injectable()
export class AppStore {

    private _store = new Map<string, BehaviorSubjectStore<any>>();

    constructor(initialState) {
        for (let event in initialState) {
            this._store.set(event, new BehaviorSubjectStore<any>(initialState[event]))
        }
    }

    select(key) {
        return this._store.get(key)
    }

